import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, getJob, toJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  let body = ''; for await (const chunk of req) { body += chunk.toString(); if (body.length > 100_000) throw new Error('too_large'); } return body;
}
function validation(body: unknown): { input: string; steps: number; failAttempts: number } | { fields: {field:string;message:string}[] } {
  const fields: {field:string;message:string}[] = [];
  if (body === null || typeof body !== 'object' || Array.isArray(body)) return { fields: [{ field: 'body', message: 'Must be a JSON object.' }] };
  const obj = body as Record<string, unknown>;
  for (const key of Object.keys(obj)) if (!['input','steps','failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
  if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'Required.' });
  else if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
  else if (obj.input.length < 1 || obj.input.length > 1000 || !obj.input.trim()) fields.push({ field: 'input', message: 'Must be 1–1000 characters and not only whitespace.' });
  const steps = Object.hasOwn(obj, 'steps') ? obj.steps : 5;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  const failAttempts = Object.hasOwn(obj, 'failAttempts') ? obj.failAttempts : 0;
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  if (fields.length) return { fields };
  return { input: obj.input as string, steps: steps as number, failAttempts: failAttempts as number };
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') { res.writeHead(200, {'content-type':'text/html; charset=utf-8'}); res.end(uiHtml); return; }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as {at:number} | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - row.at <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const jobs = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, string|number|null>[];
      return send(res, 200, { jobs: jobs.map(toJob) });
    }
    if (req.method !== 'POST') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    if (!/^application\/json(?:\s*;|\s*$)/i.test(req.headers['content-type'] ?? '')) return error(res, 400, 'invalid_request', 'Content-Type must be application/json.', [{field:'Content-Type',message:'Must be application/json.'}]);
    let raw: string;
    try { raw = await readBody(req); } catch { return error(res, 400, 'invalid_request', 'Request body is too large.', [{field:'body',message:'Request body is too large.'}]); }
    let parsed: unknown;
    try { parsed = JSON.parse(raw); } catch { return error(res, 400, 'invalid_request', 'Malformed JSON.', [{field:'body',message:'Malformed JSON.'}]); }
    const checked = validation(parsed);
    if ('fields' in checked) return error(res, 400, 'invalid_request', 'Request validation failed.', checked.fields);
    const key = req.headers['idempotency-key'];
    if (Array.isArray(key) || (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key))) return error(res, 400, 'invalid_request', 'Invalid Idempotency-Key.', [{field:'Idempotency-Key',message:'Must match ^[A-Za-z0-9_-]{1,128}$.'}]);
    const payload = JSON.stringify(checked);
    db.exec('BEGIN IMMEDIATE');
    try {
      if (key) {
        const prior = db.prepare('SELECT payload,job_id FROM idempotency WHERE key=?').get(key) as {payload:string;job_id:string}|undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This key was already used with a different payload.');
          const job = getJob(db, prior.job_id); if (job) return send(res, 200, job);
        }
      }
      const id = randomUUID(), now = new Date().toISOString();
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,retry_at)
        VALUES(?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0)`).run(id, checked.input, checked.steps, checked.failAttempts, now, now);
      if (key) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, payload, id);
      db.exec('COMMIT');
      return send(res, 201, getJob(db, id));
    } catch (e) { db.exec('ROLLBACK'); throw e; }
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const job = getJob(db, id);
    return job ? send(res, 200, job) : error(res, 404, 'not_found', 'Job not found.');
  }
  return error(res, 404, 'not_found', 'Route not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

