import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
export interface Job {
  id: string; status: JobStatus; input: string; steps: number; failAttempts: number; attempts: number;
  progress: { completed: number; total: number }; result: { output: string } | null; error: string | null;
  createdAt: string; updatedAt: string;
}
type Row = Record<string, string | number | null>;

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout=5000; PRAGMA journal_mode=WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, progress_completed INTEGER NOT NULL DEFAULT 0,
      result_output TEXT, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
      retry_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status, retry_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id=1), at INTEGER NOT NULL);
  `);
  return db;
}

export function toJob(row: Row): Job {
  return {
    id: String(row.id), status: row.status as JobStatus, input: String(row.input), steps: Number(row.steps),
    failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.progress_completed), total: Number(row.steps) },
    result: row.result_output === null ? null : { output: String(row.result_output) },
    error: row.error === null ? null : String(row.error), createdAt: String(row.created_at), updatedAt: String(row.updated_at),
  };
}

export function getJob(db: DatabaseSync, id: string): Job | null {
  const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Row | undefined;
  return row ? toJob(row) : null;
}

