import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
// A running row is an abandoned lease after process loss. Leave its attempt count intact;
// claiming it again starts the next attempt and resets progress.
db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, retry_at=0, updated_at=? WHERE status='running'`).run(new Date().toISOString());
const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 750);
let stopping = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping = true; });

type Claimed = { id: string; input: string; steps: number; fail_attempts: number; attempts: number };
function claim(): Claimed | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare(`SELECT id,input,steps,fail_attempts,attempts FROM jobs
      WHERE status='queued' AND retry_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as Claimed | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const now = new Date().toISOString();
    db.prepare(`UPDATE jobs SET status='running',attempts=attempts+1,progress_completed=0,updated_at=? WHERE id=? AND status='queued'`).run(now,row.id);
    db.exec('COMMIT');
    return { ...row, attempts: row.attempts + 1 };
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}
async function processJob(job: Claimed): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated dependency fails before the first step, leaving progress at zero.
    const now = new Date().toISOString();
    if (job.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed',error='transient failure',result_output=NULL,updated_at=?,retry_at=0 WHERE id=?`).run(now,job.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued',error=NULL,result_output=NULL,progress_completed=0,retry_at=?,updated_at=? WHERE id=?`).run(Date.now()+500,now,job.id);
    }
    return;
  }
  for (let step=1; step<=job.steps; step++) {
    await sleep(100);
    db.prepare(`UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'`).run(step,new Date().toISOString(),job.id);
  }
  db.prepare(`UPDATE jobs SET status='completed',result_output=?,error=NULL,updated_at=?,retry_at=0 WHERE id=? AND status='running'`).run(job.input.toUpperCase(),new Date().toISOString(),job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const job = claim();
    if (!job) { await sleep(100); continue; }
    await processJob(job);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.close();
}

