10	    label{display:block;margin:12px 0 4px;font-weight:600} input{font:inherit;padding:8px;border:1px solid #aebac5;border-radius:5px}
11	    #job-input{display:block;width:min(100%,440px)} button{margin-top:16px;padding:9px 15px;font:inherit;color:white;background:#175e9c;border:0;border-radius:5px;cursor:pointer}
12	    [role=alert]{color:#a32222;white-space:pre-line;margin-top:12px}.job h3{margin:0 0 8px;overflow-wrap:anywhere}.muted{color:#53616d}
13	  </style>
14	</head>
15	<body>
16	  <h1>Job tracker</h1>
17	  <p class="muted">Submit work and follow its progress.</p>
18	  <form data-testid="job-form">
19	    <label for="input">Input</label><input data-testid="job-input" id="input" name="input" type="text" required maxlength="1000">
20	    <label for="steps">Steps</label><input data-testid="job-steps" id="steps" name="steps" type="number" min="1" max="20" step="1" value="5">
21	    <label for="failAttempts">Fail attempts</label><input data-testid="job-fail-attempts" id="failAttempts" name="failAttempts" type="number" min="0" max="5" step="1" value="0">
22	    <br><button data-testid="job-submit" type="submit">Submit job</button>
23	    <div data-testid="form-error" role="alert" aria-live="polite"></div>
24	  </form>
25	  <h2>Jobs</h2>
26	  <div data-testid="job-list" aria-live="polite"></div>
27	  <script>
28	    const form=document.querySelector('[data-testid="job-form"]');
29	    const errorRegion=document.querySelector('[data-testid="form-error"]');
30	    const list=document.querySelector('[data-testid="job-list"]');
31	    const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
32	    async function refresh(){
33	      try{
34	        const response=await fetch('/api/jobs'); if(!response.ok)return;
35	        const {jobs}=await response.json();
36	        list.innerHTML=jobs.map(j=>`<section class="job" data-testid="job-item" data-job-id="${esc(j.id)}"><h3>${esc(j.input)}</h3><div>Status: <span data-testid="job-status">${esc(j.status)}</span></div><div>Progress: <span data-testid="job-progress">${j.progress.completed}/${j.progress.total}</span></div><div>Result: <span data-testid="job-result">${esc(j.result?.output??j.error??'')}</span></div></section>`).join('');
37	      }catch{}
38	    }
39	    form.addEventListener('submit',async event=>{
40	      event.preventDefault(); errorRegion.textContent='';
41	      const input=form.elements.input.value;
42	      const steps=Number(form.elements.steps.value);
43	      const failAttempts=Number(form.elements.failAttempts.value);
44	      try{
45	        const response=await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input,steps,failAttempts})});
46	        const body=await response.json();
47	        if(!response.ok){const e=body.error??{};const fields=Array.isArray(e.fields)?e.fields.map(f=>`${f.field}: ${f.message}`).join('\n'):'';errorRegion.textContent=[e.message,fields].filter(Boolean).join('\n');return;}
48	        form.elements.input.value=''; await refresh();
49	      }catch{errorRegion.textContent='Could not submit the job. Please try again.';}
50	    });
51	    refresh(); setInterval(refresh,700);
52	  </script>
53	</body>
54	</html>
